// Des: Start the app: read args, config, lock, open state
// Flo: args > aa-conf-main.json > data folder (stat + prof) > lock (one run at a time) > state db > (browser commands) launch own-profile Chrome + tab > dispatch > print errors in the owner's language
// I/O: process Init (caller) > exit code 0-4; browser profile in <data>/prof, state in <data>/stat (data = data_loca_wind / data_loca_unix)
// ===================================================================
const std = @import("std"); const logz = @import("lo-logz-line.zig"); const aliv = @import("ct-comm-aliv.zig"); const envl = @import("ct-ctrl-envl.zig"); const cfgz = @import("cf-conf-load.zig"); const targ = @import("ct-ctrl-args.zig"); const runz = @import("ct-ctrl-runz.zig"); const task = @import("ru-task-runn.zig"); const stat = @import("st-stat-main.zig"); const chro = @import("nt-brow-chro.zig"); const pg = @import("ru-page-snap.zig"); const pace = @import("ru-huma-pace.zig"); const lock = @import("ru-lock-main.zig"); const priv = @import("ru-safe-priv.zig"); const erro = @import("er-erro-type.zig"); const misc = @import("ct-comm-misc.zig"); const secr = @import("ru-secr-refs.zig"); const acctm = @import("ru-acct-main.zig");
const HELP_EN = "fb-face-webs: Facebook helper that works like you, at a human pace.\n  fb-face-webs setup [--yes]            first run: browser, login, check, demo, accept the risk (--yes)\n  fb-face-webs login                    open the browser, log in by hand\n  fb-face-webs status [--json]          limits, warm-up, quiet hours, last stop, last flow\n  fb-face-webs jobs                     every job, its risk (W = ok, X = needs your OK) and limit\n  fb-face-webs run <job> [flags]        one job, e.g. post, reply, friend-accept, market-edit\n  fb-face-webs ask \"<words>\"            e.g. \"post: hello\" | \"reply to my comments\" | \"renew my listings\"\n  fb-face-webs plan <routine>           list what a routine will do and what needs your OK\n  fb-face-webs approve all | 1,3        approve once, up front (fb-face-webs deny 2 to refuse)\n  fb-face-webs flow run <routine>       run a routine by itself; it pauses only when it needs you\n  fb-face-webs doctor [job] [--url p]   check the buttons each job needs (read-only)\n  fb-face-webs alive [--live]           is each account still logged in (no flag: saved state only; --live: look once, read-only)\n  fb-face-webs snap <path> [name]       save a redacted copy of a page for testing (read-only)\n  fb-face-webs read <noti|requests|birthdays|inbox|market-inbox|msgr-requests|feed>\n  fb-face-webs start --live             zero start: log in from the secrets file, check the buttons, map the site\n  fb-face-webs secret [--json]          which secret fields are filled (never the values)\n  fb-face-webs map                      read-only map of the site's pages and controls (human pace)\n  fb-face-webs gaps [matrix] [--json]   compare the map with the jobs: changed buttons, new controls | job list by area\n  fb-face-webs ledger | log [--json]    Marketplace ledger | recent actions\n  fb-face-webs pause | resume           stop or allow running jobs (resume also ends a safety rest)\n  fb-face-webs unlock <key>             clear an unsure key after you checked Facebook\n  fb-face-webs report | backup | export | purge     support folder | copy of your data | JSONL export | delete old logs\nflags: --text --to --url --title --price --desc --group --photo --opt --date --time --catg --cond --loca --max N --conf <file> --acct <id>|all --head --yes\nsafety: default is a dry-run preview. --read = read only. --live = do it. --live --force = also approve risky acts.\nexit: 0 ok | 1 failed | 2 usage | 3 page changed | 4 blocked (quiet hours, cap, challenge, approval, rest)";
const HELP_VI = "fb-face-webs: trợ lý Facebook làm việc như bạn, với nhịp như người thật.\n  fb-face-webs setup [--yes]            lần đầu: trình duyệt, đăng nhập, kiểm tra, thử mẫu, chấp nhận rủi ro (--yes)\n  fb-face-webs login                    mở trình duyệt, tự đăng nhập\n  fb-face-webs status [--json]          hạn mức, khởi động chậm, giờ nghỉ, lần dừng cuối, quy trình cuối\n  fb-face-webs jobs                     mọi việc, mức rủi ro (W = ok, X = cần bạn duyệt) và hạn mức\n  fb-face-webs run <việc> [cờ]          một việc, vd: post, reply, friend-accept, market-edit\n  fb-face-webs ask \"<lời nói>\"           vd: \"post: xin chào\" | \"reply to my comments\" | \"renew my listings\"\n  fb-face-webs plan <quy trình>         xem quy trình sẽ làm gì và việc nào cần bạn duyệt\n  fb-face-webs approve all | 1,3        duyệt một lần từ đầu (fb-face-webs deny 2 để từ chối)\n  fb-face-webs flow run <quy trình>     chạy tự động; chỉ dừng khi thật sự cần bạn\n  fb-face-webs doctor [việc] [--url p]  kiểm tra các nút mỗi việc cần (chỉ đọc)\n  fb-face-webs alive [--live]           mỗi tài khoản còn đăng nhập không (không cờ: chỉ đọc trạng thái đã lưu; --live: mở xem một lần)\n  fb-face-webs snap <đường dẫn> [tên]   lưu bản sao đã che thông tin của trang để thử nghiệm (chỉ đọc)\n  fb-face-webs read <noti|requests|birthdays|inbox|market-inbox|msgr-requests|feed>\n  fb-face-webs start --live             bắt đầu từ số 0: đăng nhập từ tệp bí mật, kiểm tra nút, vẽ bản đồ trang\n  fb-face-webs secret [--json]          các trường bí mật đã điền (không bao giờ hiện giá trị)\n  fb-face-webs map                      bản đồ chỉ-đọc các trang và nút của site (nhịp như người)\n  fb-face-webs gaps [matrix] [--json]   so bản đồ với các việc: nút đổi tên, nút mới | danh sách việc theo nhóm\n  fb-face-webs ledger | log [--json]    sổ Marketplace | hành động gần đây\n  fb-face-webs pause | resume           dừng hoặc cho phép chạy (resume cũng kết thúc giờ nghỉ an toàn)\n  fb-face-webs unlock <khóa>            mở khóa sau khi bạn đã kiểm tra Facebook\n  fb-face-webs report | backup | export | purge     thư mục hỗ trợ | bản sao dữ liệu | xuất JSONL | xóa nhật ký cũ\ncờ: --text --to --url --title --price --desc --group --photo --opt --date --time --catg --cond --loca --max N --conf <tệp> --acct <id>|all --head --yes\nan toàn: mặc định chỉ xem trước. --read = chỉ đọc. --live = làm thật. --live --force = duyệt luôn việc rủi ro.\nmã thoát: 0 ok | 1 lỗi | 2 sai lệnh | 3 trang đã đổi | 4 bị chặn (giờ nghỉ, hạn mức, kiểm tra bảo mật, cần duyệt, nghỉ an toàn)";
const CF = .{ .file = "aa-conf-main.json", .cand = [_][]const u8{ "..", "../..", "." }, .dbfi = "fb-state.db", .subs = "stat", .subp = "prof", .boot = 30000, .conn = 8000 };
fn confFind(allo: std.mem.Allocator, iozz: std.Io, args: targ.Args) !cfgz.Conf { if (args.conf.len > 0) return cfgz.confLoad(allo, iozz, args.conf); const dirz = std.process.executableDirPathAlloc(iozz, allo) catch "."; for (CF.cand) |rela| { const path = std.fs.path.join(allo, &.{ dirz, rela, CF.file }) catch continue; _ = std.Io.Dir.cwd().statFile(iozz, path, .{}) catch continue; return cfgz.confLoad(allo, iozz, path); } return .{}; }
fn outz(iozz: std.Io, text: []const u8) void { std.Io.File.stdout().writeStreamingAll(iozz, text) catch {}; }
fn emit(init: std.process.Init, args: targ.Args, text: []const u8) void { if (args.sink) |snk| { snk.appendSlice(init.arena.allocator(), text) catch {}; return; } outz(init.io, text); }
fn fileHave(iozz: std.Io, path: []const u8) bool { _ = std.Io.Dir.cwd().statFile(iozz, path, .{}) catch return false; return true; }
fn failz(conf: cfgz.Conf, err: anyerror) u8 { const msg = erro.mesgLang(err, conf.lang_main_code); logz.logz("main", .erro, msg.what, msg.whyz, msg.fixz); return erro.exitCode(err); }
const KEEP = [_][]const u8{ "secret", "jobs" };
const AllSt = struct { init: std.process.Init, args: targ.Args, conf: cfgz.Conf, book: secr.Book, root: []const u8 };
fn say(px: ?*anyopaque, msg: []const u8) void { const st: *AllSt = @ptrCast(@alignCast(px.?)); const line = std.fmt.allocPrint(st.init.arena.allocator(), "{s}\n", .{msg}) catch return; emit(st.init, st.args, line); }
fn runner(px: ?*anyopaque, id: []const u8) anyerror!void { const st: *AllSt = @ptrCast(@alignCast(px.?)); _ = workOne(st.init, st.args, st.conf, st.book, id, st.root) catch |err| { _ = failz(st.conf, err); return err; }; }
fn workOne(init: std.process.Init, args: targ.Args, conf0: cfgz.Conf, book: secr.Book, id: []const u8, root: []const u8) !u8 { const allo = init.arena.allocator(); const iozz = init.io; const home = init.environ_map.get("USERPROFILE") orelse init.environ_map.get("HOME") orelse ""; const user = priv.ownerId(allo, iozz, init.environ_map.get("SystemRoot") orelse "") catch "";
const acc = secr.pick(book, id) orelse return error.BadUsage; var conf = acctm.applyScal(conf0, acc.scal); if (std.mem.eql(u8, acc.lang, "vi") or std.mem.eql(u8, acc.lang, "en")) conf.lang_main_code = acc.lang;
const secd = secr.dirOf(allo, home, conf) catch ""; const adir = try std.fs.path.join(allo, &.{ root, "acct", id }); const sdir = try std.fs.path.join(allo, &.{ adir, CF.subs }); if (!args.quiet()) try std.Io.Dir.cwd().createDirPath(iozz, sdir);
var brow_cmd = runz.needBrow(args); var lck: ?lock.Lock = null; defer if (lck) |*lk| lk.release(); if (brow_cmd) lck = try lock.take(init.gpa, iozz, sdir);
const dbf = try std.fs.path.joinZ(allo, &.{ sdir, CF.dbfi }); const dbp: [:0]const u8 = if (args.quiet() and !fileHave(iozz, dbf)) ":memory:" else dbf; var store = try stat.Stat.open(allo, dbp); defer store.close();
var look = false; if (!brow_cmd and std.mem.eql(u8, args.cmdz, "alive") and aliv.takeLook(&store, conf, @intCast(std.Io.Clock.real.now(iozz).toMilliseconds()), id)) { look = true; brow_cmd = true; lck = try lock.take(init.gpa, iozz, sdir); }
var seed = conf.rand_seed_numb; if (seed == 0) { var sb: [8]u8 = undefined; iozz.random(&sb); seed = std.mem.readInt(u64, &sb, .little); } var rng = pace.Rng.init(seed); if (brow_cmd) { const nw: i64 = @intCast(std.Io.Clock.real.now(iozz).toMilliseconds()); store.logAdd("pace", try pace.startz(allo, &rng, id, seed, nw), true, nw) catch {}; } var page: pg.Page = undefined; var brow: ?chro.Brow = null; defer if (brow) |*brw| brw.stop(); var opened = false; defer if (opened) page.closeConn();
if (brow_cmd) { const exe = (try chro.exeFind(allo, iozz, conf.brow_exec_path)) orelse return error.NoBrowser; const prof = try std.fs.path.join(allo, &.{ adir, CF.subp }); brow = chro.launch(allo, iozz, exe, prof, conf.brow_head_mode or args.head, .{ .widt = conf.brow_wind_widt, .high = conf.brow_wind_high, .scal = conf.brow_wind_scal, .left = conf.brow_wind_left }, CF.boot) catch return error.BrowFail; const wsp = try chro.pageWs(allo, iozz, brow.?.port, CF.boot); page = try pg.pageOpen(allo, iozz, brow.?.port, wsp, CF.conn); opened = true; page.arm(conf.brow_time_seco * 1000); try page.enable(allo); }
var ctx: task.Ctx = .{ .gpaz = init.gpa, .aren = allo, .iozz = iozz, .conf = conf, .store = &store, .mode = args.mode(), .page = &page, .rng = &rng, .base = conf.base_urlz_main, .statd = sdir, .grant = try priv.grantFor(allo, user), .dataroot = adir, .feedd = cfgz.feedDir(allo, home, conf) catch "", .secrd = secd, .secr = secr.toSecr(acc), .acct = id, .sink = args.sink, .look = look }; const done = runz.dispatch(&ctx, args) catch |err| { if (err == error.NeedLogin and brow_cmd) aliv.markPut(&ctx, aliv.DEAD); return err; }; if (brow_cmd and std.mem.eql(u8, args.cmdz, "read")) aliv.markPut(&ctx, aliv.OK); return done; }
fn work(init: std.process.Init, args: targ.Args, conf: cfgz.Conf) !u8 { const allo = init.arena.allocator(); const iozz = init.io; const home = init.environ_map.get("USERPROFILE") orelse init.environ_map.get("HOME") orelse "";
const root = cfgz.dataDir(allo, home, conf) catch return error.BadConfig; if (!args.quiet()) { try std.Io.Dir.cwd().createDirPath(iozz, root); _ = acctm.migrate(allo, iozz, root) catch false; }
const secd = secr.dirOf(allo, home, conf) catch ""; const book = try secr.loadBook(allo, iozz, secd, conf.acct_maxx_coun);
var keep = false; for (KEEP) |nm| { if (std.mem.eql(u8, nm, args.cmdz)) keep = true; }
if (!std.mem.eql(u8, args.acct, "all") or keep) { const id = if (args.acct.len > 0 and !std.mem.eql(u8, args.acct, "all")) args.acct else book.main; if (!secr.idOk(id)) return error.BadUsage; return workOne(init, args, conf, book, id, root); }
const brow_cmd = runz.needBrow(args); var gl: ?lock.Lock = null; defer if (gl) |*lk| lk.release(); if (brow_cmd) { const gdir = try std.fs.path.join(allo, &.{ root, "acct" }); try std.Io.Dir.cwd().createDirPath(iozz, gdir); gl = try lock.take(init.gpa, iozz, gdir); }
var ids: std.ArrayList([]const u8) = .empty; for (book.accs) |acc| try ids.append(allo, acc.id); var sb: [8]u8 = undefined; iozz.random(&sb); var rng = pace.Rng.init(std.mem.readInt(u64, &sb, .little)); var st: AllSt = .{ .init = init, .args = args, .conf = conf, .book = book, .root = root }; const now: i64 = @intCast(std.Io.Clock.real.now(iozz).toMilliseconds());
var env: acctm.Env = .{ .aren = allo, .iozz = iozz, .conf = conf, .root = root, .ids = ids.items, .now = now, .rng = &rng, .ctx = &st, .run = runner, .say = say, .browser = brow_cmd }; const res = try acctm.runAll(&env); for (res) |rs| { const line = try std.fmt.allocPrint(allo, "account {s}: {s}\n", .{ rs.id, rs.state }); emit(init, args, line); } return acctm.worst(res); }
fn failJ(init: std.process.Init, args: targ.Args, jsnz: bool, lang: []const u8, err: anyerror) u8 { const msg = erro.mesgLang(err, lang); logz.logz("main", .erro, msg.what, msg.whyz, msg.fixz); const code = erro.exitCode(err); if (jsnz) { const allo = init.arena.allocator(); const text = std.fmt.allocPrint(allo, "{s} - {s}; fix: {s}", .{ msg.what, msg.whyz, msg.fixz }) catch return code; const docz = envl.failDoc(allo, args.cmdz, code, @errorName(err), text, if (args.writes()) !args.live else null) catch return code; outz(init.io, std.fmt.allocPrint(allo, "{s}\n", .{docz}) catch return code); } return code; }
fn runCore(init: std.process.Init, args: targ.Args, conf: cfgz.Conf) !u8 { const iozz = init.io; if (args.helz or args.cmdz.len == 0 or std.mem.eql(u8, args.cmdz, "help")) { const text = if (std.mem.eql(u8, conf.lang_main_code, "vi")) HELP_VI ++ "\n" else HELP_EN ++ "\n"; if (args.cmdz.len == 0 and !args.helz) { std.debug.print("{s}", .{text}); return 2; } emit(init, args, text); return 0; } if (std.mem.eql(u8, args.cmdz, "version")) { emit(init, args, "fb-face-webs " ++ misc.VERS ++ "\n"); return 0; } if (!args.known()) { logz.logz("args", .erro, "unknown command", args.cmdz, "run: face help"); return error.BadUsage; } _ = iozz; return work(init, args, conf); }
pub fn runMain(init: std.process.Init) !u8 { const allo = init.arena.allocator(); const iozz = init.io; var iter = try init.minimal.args.iterateAllocator(allo); _ = iter.next(); var argv: std.ArrayList([]const u8) = .empty; while (iter.next()) |item| try argv.append(allo, item); var jsnz = false; for (argv.items) |item| { if (std.mem.eql(u8, item, "--json")) jsnz = true; } var args = targ.argsRead(argv.items) catch |err| return failJ(init, .{}, jsnz, "en", err); var sink: std.ArrayList(u8) = .empty; if (jsnz) args.sink = &sink; const conf = confFind(allo, iozz, args) catch |err| return failJ(init, args, jsnz, "en", err); const code = runCore(init, args, conf) catch |err| return failJ(init, args, jsnz, conf.lang_main_code, err); if (jsnz) { const docz = try envl.okayDoc(allo, if (args.cmdz.len == 0) "help" else args.cmdz, code, sink.items, if (args.writes()) !args.live else null); outz(iozz, try std.fmt.allocPrint(allo, "{s}\n", .{docz})); } return code; }
